// May 2026 Hillside Homeowners and Residents Information Handbook.
// These topic-sized records are intentionally easier for Lenox to retrieve than one large document.
const handbookEntries = [
  { category: "Handbook: Governance and Condo Documents", keywords: ["condo docs", "bylaws", "declaration", "governance", "homeowners association", "hoa rules"], answer: "Hillside is a condominium community: owners hold their individual units and share common areas. The Declaration of Condominium and Bylaws (the Condo Docs) are legally binding and take precedence over other community policies. The Handbook provides practical day-to-day guidance but does not override the Condo Docs." },
  { category: "Handbook: Property Management and Vantaca", keywords: ["heritage", "property manager", "amber nash", "vantaca", "work order", "assessment", "payment history"], answer: "Hillside is managed by Heritage Property Management Services. Amber Nash, CMCA, is the Portfolio Manager; email anash@heritageproperty.com or call 770-200-8610. For common-area work orders, documents, payment history, requests, FAQs, and calendar items, residents should first use Vantaca at https://portal.heritageproperty.com. The Heritage main line is 770-451-8171." },
  { category: "Handbook: New Resident Essentials", keywords: ["new resident", "new homeowner", "utilities", "mailbox", "fob", "key fob", "internet", "water", "gas"], answer: "New residents should set up utilities, register in the Hillside website, complete the Homeowner Information Sheet, register vehicles, arrange HOA assessment payments, and provide emergency key/alarm details to the Board. Georgia Power: 888-660-5890; water/sewer billing: Conservice 866-947-7379; internet providers include AT&T, Google Fiber, and Comcast. Contact the Board for additional fobs, remotes, stairwell combinations, or mailbox-key guidance. Do not share building access codes with non-residents." },
  { category: "Handbook: Move In and Move Out", keywords: ["move", "move in", "move out", "moving", "elevator pads", "garage", "move fee"], answer: "Schedule a move with Heritage and copy board@hillsideatlenox.com at least two weeks ahead. Moving hours are 8:00 AM–7:00 PM and the move fee is $500. Moves must use the garage—not the front entrance—and must not block the garage. Elevator pads and floor coverings are required; failure to use them carries a $100 charge plus any damage. Movers may use only the garage and the unit floor, common areas must be cleaned after the move, and moving debris may not go in hallways, trash rooms, or chutes." },
  { category: "Handbook: Emergency Access and Common Areas", keywords: ["emergency key", "alarm code", "common area damage", "camera", "cctv", "common areas"], answer: "Owners must provide the Board with a current door key and, if applicable, alarm code for emergency access; refusal can result in fines. Report damage or disrespect of common areas to the Board. Hillside has CCTV in many common areas for after-the-fact review and rule observance; cameras are not monitored 24/7 and are not a substitute for personal security." },
  { category: "Handbook: Safety and Community Watch", keywords: ["community watch", "doc", "derek cox", "crime", "tailgate", "security", "911", "stolen fob"], answer: "For an active crime, fire, medical emergency, or dangerous situation, call 911 first. Hillside Community Watch can be reached at 404-883-3350 or 811 on Hillside callboxes for non-emergency concerns such as loitering, tailgating, suspicious activity, smoking/vaping in common areas, or mailroom concerns. Report lost or stolen fobs to the Board immediately for deactivation. Do not let unknown people follow you into the building." },
  { category: "Handbook: Parking and Towing", keywords: ["parking", "tow", "a-tow", "front driveway", "red zone", "fire lane", "handicapped", "assigned space"], answer: "Garage spaces are assigned; do not use another resident’s space without written permission. Do not park in front of the building for more than 30 minutes, in the red-zone fire lane, or in a handicapped space. A-Tow: 404-577-8950. Parking violations can lead to towing and fines." },
  { category: "Handbook: Common Area Maintenance", keywords: ["common area maintenance", "burned out light", "fitness equipment", "water leak", "gas leak", "flood", "sewage"], answer: "Report common-area damage or maintenance issues to both Heritage and board@hillsideatlenox.com. For critical issues such as gas or water leaks, alarms, fire, illness, or death, call 911 immediately. Heritage coordinates common-area repairs; owners are responsible for costs associated with issues inside their own units." },
  { category: "Handbook: Unit Maintenance and Fire Safety", keywords: ["water shutoff", "water heater", "ac", "air conditioner", "bleach", "smoke detector", "sprinkler", "fireplace", "pest control"], answer: "Know your unit’s main water shut-off valve in the water-heater closet; turn the blue-handled valve horizontal to stop water flow. Maintain appliances and A/C drains, pour one cup of bleach into the A/C drain monthly, and change air-handler filters at least every three months. Keep smoke detectors working, do not paint sprinkler heads, and never leave fireplaces or candles unattended. Annual fire/sprinkler inspection access is mandatory. Association pest control is quarterly; contact the Board for details." },
  { category: "Handbook: Leasing and Short-Term Rentals", keywords: ["lease", "leasing permit", "rental", "tenant", "airbnb", "vrbo", "sublease", "hardship lease"], answer: "A homeowner in good standing who has lived at Hillside at least two years may be eligible to apply for a lease permit. The Condo Docs cap permits at 14; a unit vacant for more than 90 days between tenants loses its permit and must reapply. Subleasing, Airbnb, VRBO, and similar short-term rentals are prohibited. Renting without a permit may result in a $150-per-day fine. Tenants must receive the Handbook, agree to follow it, and provide required documentation and occupant information." },
  { category: "Handbook: Noise and Neighbor Relations", keywords: ["noise", "quiet hours", "loud music", "party", "10 pm", "neighbor"], answer: "Residents are entitled to quiet enjoyment. Noise ordinances take effect at 10:00 PM. First try a neighborly resolution; for recurring issues, contact Heritage, which can send a complaint letter without disclosing the reporting resident. Call 911 if the issue is severe or continues after other measures. Noise between 10 PM and 7 AM can result in a $100 fine." },
  { category: "Handbook: Pets", keywords: ["pet", "dog", "leash", "pet waste", "lobby", "pool", "dog fee"], answer: "Dogs must be leashed outside the unit; use the designated rear parking pet area and dispose of waste properly. Pets are never allowed at the pool and may enter the lobby only when carried or in a carrier. Do not place pet waste in recycling or the mailroom receptacle. The annual dog fee is $100, with a maximum of two dogs. Pet-rule violations may be fined." },
  { category: "Handbook: Trash and Recycling", keywords: ["trash", "garbage", "recycling", "glass recycling", "cardboard", "furniture", "electronics", "bulk item", "dumpster"], answer: "Place garbage in secured plastic bags; rinse liquid containers before disposal. Put closed bags in the trash bin at the bottom of the chute in the north-garage dumpster room. Recycle paper, flattened cardboard, plastic bottles, and cans; glass is not accepted in recycling. Large items and electronics are not allowed in the dumpster room—store them until the biannual bulk pickup or arrange individual pickup. Large-item disposal may be fined $500 plus removal cost." },
  { category: "Handbook: Balconies, Storage, and Dress", keywords: ["balcony", "patio", "grill", "satellite dish", "laundry", "storage", "hazardous materials", "dress code"], answer: "Electric grills are allowed only if not visible from the street; fire grills are prohibited. Do not hang laundry, towels, rugs, or other items from balconies, and do not leave visible clutter or satellite dishes. No hazardous or flammable materials may be stored in storage units or water-heater closets. Shirts, bottoms, and footwear are required in common areas except poolside." },
  { category: "Handbook: Architectural Requests and Renovations", keywords: ["architectural", "renovation", "remodel", "contractor", "remove wall", "flooring", "construction", "approval"], answer: "Major modifications, wall removal, projects using a general contractor or multiple trades, multi-day vendor work, and major repairs require prior Board approval through an Architectural Submission. Include plans, photos, permits, contractor insurance, and structural-engineer documentation when applicable. No work may begin before approval. Notify neighbors of anticipated noise; noisy work is limited to 8 AM–7 PM. New hardwood flooring needs specified soundproof underlay, and sprinkler heads must never be painted." },
  { category: "Handbook: Common Areas and Pool", keywords: ["pool", "grill", "glass", "pool guests", "private party", "common area", "amenity"], answer: "Clean and restore common areas after use; residents are responsible for guest damage. Private parties are not allowed at the pool. Residents may have up to three guests. Glass and other breakable containers are prohibited in the pool area by Georgia law and may result in a $200 fine. Clean and cover the grill after use; email the Board if propane needs replacement." },
  { category: "Handbook: Club Room", keywords: ["club room", "clubroom", "reservation", "club room fee", "club room deposit", "party room"], answer: "Email board@hillsideatlenox.com first to check date availability. Submit the reservation form with a $150 rental fee and separate $200 refundable damage-deposit check. Events are limited to 25 guests and must end by 10 PM. Guests must stay with an authorized resident. Do not move club-room furniture or the pool table; the pool is not included. No smoking, vaping, glitter, or confetti. The reserving resident must clean up and is responsible for damage." },
  { category: "Handbook: Fitness Room and Sauna", keywords: ["fitness", "gym", "sauna", "infrared sauna", "workout"], answer: "The fitness room is for residents only; children under 18 are not allowed, blinds should be closed in the evening, and use is at the resident’s risk. Sauna users must wear modest appropriate attire, bring a clean towel, shower first, keep electronics/food/drinks out, limit sessions to 30 minutes, and leave if dizzy or unwell. Sauna use is at the resident’s risk; violations may be fined." },
  { category: "Handbook: Contractors and Communications", keywords: ["vendor", "contractor", "whatsapp", "communications", "updates", "contact information"], answer: "Owners are responsible for contractor access and activity. Contractors must follow the Move-In/Move-Out Guidelines and can be expelled for violations, with fines assessed to the involved owner. Keep your phone number and email current with the Board and Heritage, and join the Hillside WhatsApp group for updates. Submit questions to Heritage in Vantaca or email board@hillsideatlenox.com." },
  { category: "Handbook: Board and Management Roles", keywords: ["board role", "management role", "board meeting", "homeowner responsibilities", "hoa meeting"], answer: "Homeowners must maintain their units, follow the Condo Docs and Handbook, report maintenance/security/rule issues, pay assessments, and participate in the HOA. The Board governs in the association’s best interest; day-to-day community issues should generally go first to Heritage. Board meetings are generally the third Thursday monthly at 6:30 PM, along with quarterly and annual homeowner meetings. Contact the Board in writing or at an association meeting rather than at members’ homes or workplaces." },
  { category: "Handbook: Who To Call", keywords: ["elevator", "gate", "front door", "club room access", "break in", "vehicle theft", "fire", "illness", "weather emergency"], answer: "For elevator, gate, elevator-lobby, front-door, or club-room access problems, contact Amber Nash and the Board. For fire, illness, death, personal attack, break-in, or vehicle theft, call 911 first, then Heritage. For weather emergencies, follow local news and mandatory evacuation orders. For rule violations, contact Heritage and inform the Board; provide photos, witnesses, and documentation when possible because hearsay alone is insufficient." },
  { category: "Handbook: Fees and Fines", keywords: ["fine", "fees", "violation fine", "move fine", "smoking fine", "glass fine", "late dues"], answer: "Selected fees: replacement hybrid fob/clicker $50, security-directory change $20, move fee $500, and annual dog fee $100. Repeat violations of the same type escalate: second is doubled, third tripled, and fourth/subsequent violations multiply by the number incurred. Examples include $400 for smoking/vaping indoors in common areas, $200 for glass at the pool, $300 for failing to schedule a move, and $150–$250 per day for illegal rentals. The Board determines fines not specified in the schedule." },
  { category: "Condo Docs: Authority and Precedence", keywords: ["ccr", "cc&r", "condo docs", "declaration", "bylaws", "articles", "precedence", "legal authority"], answer: "For Hillside at Lenox, the Declaration of Condominium and Bylaws are the foundational Condo Docs. They are legally binding on owners and residents, define the Association and Board authority, set rules for units and common areas, and provide the basis for assessments and enforcement. If the Handbook or a form conflicts with the Declaration, Bylaws, or Articles of Incorporation, the recorded Condo Docs prevail." },
  { category: "Condo Docs: Owner Duties", keywords: ["owner duties", "homeowner responsibilities", "assessments", "dues", "hoa dues", "monthly dues", "records"], answer: "Owners are expected to read and follow the Condo Docs and Handbook, maintain their units, pay assessments on time, keep emergency/contact information current, provide occupant and vehicle information, report maintenance/security/rule issues, and participate in Association life. Monthly Association dues should be paid by the 5th of each month to avoid late fees." },
  { category: "Condo Docs: Emergency Access Requirement", keywords: ["emergency access", "door key", "alarm code", "unit access", "out of town", "emergency key"], answer: "Owners must provide the Board with a current unit door key and alarm code if applicable for emergency access. This requirement is described as required by the Condo Documents and exists for community safety. Refusal to provide emergency access information may result in fines. Keys are kept in a secured area and are for emergency use." },
  { category: "Condo Docs: Leasing Permit Policy", keywords: ["leasing permit", "lease permit", "rental policy", "rental cap", "14 permits", "hardship lease", "waiting list"], answer: "The Condo Docs establish a cap of 14 lease permits and rules for hardship permits. Homeowners who have lived at Hillside for more than two years and are in good standing may be eligible to apply. Eligible owners can join the leasing wait list by submitting a lease permit application, and the Board must decide within 14 days of receiving the request. A leased unit vacant for more than 90 days between tenants loses its permit and must reapply." },
  { category: "Condo Docs: Leasing Restrictions and Tenant Duties", keywords: ["tenant", "renter", "lease agreement", "sublease", "airbnb", "vrbo", "short term rental", "hosting"], answer: "Renters must agree in writing to follow the Hillside Condo Docs and Handbook. Owners must provide the Board with a copy of the 1-to-2-year lease agreement and required tenant/occupant information. Subleasing is prohibited. Airbnb, VRBO, and similar short-term or hosting-site rentals are absolutely prohibited. Renting without a permit may be fined $150 per day." },
  { category: "Condo Docs: Leasing Permit Loss", keywords: ["lose leasing permit", "tenant violation", "serious offense", "rental violation", "permit loss"], answer: "If a tenant incurs more than one fineable, serious offense, the homeowner may lose the leasing permit for one year. The definition of a fineable, serious offense remains at the HOA Board’s discretion. Non-resident homeowners may own only one property for lease, and non-resident investors for rental are not allowed by the HOA." },
  { category: "Resident Forms: Homeowner Information Sheet", keywords: ["homeowner information sheet", "resident information", "occupants", "emergency contact", "storage units", "pets", "unit number"], answer: "Owners should complete and return the Homeowner Information Sheet with unit number, owner/resident names, contact details, emergency contacts, vehicle details, storage-unit information, pet count, alarm/emergency access details, and authorized occupants. Updates should be provided promptly when information changes." },
  { category: "Resident Forms: Vehicle Registration", keywords: ["vehicle registration", "car registration", "license plate", "tag", "parking registration", "vehicle"], answer: "Residents should register vehicle information with the Board, including unit number, registered owner, contact phone, vehicle make/model/color, license plate/tag number, and assigned parking information. Vehicle and access records help with enforcement, towing questions, and security review." },
  { category: "Access Devices and Building Codes", keywords: ["fob", "remote", "clicker", "stairwell code", "access code", "front door", "garage gate"], answer: "Residents receive key fobs/remotes for the front door, garage elevator lobby, garage gate, and clubroom. Additional access devices can be requested by emailing board@hillsideatlenox.com. Stairwell combinations are provided by the Board and change periodically. Do not provide building or gate access codes to non-residents. Owners are responsible for giving access devices to renters and retrieving them at move-out." },
  { category: "Security: CCTV and Access Records", keywords: ["cctv", "camera", "security camera", "access records", "footage", "live images"], answer: "Hillside has 32 CCTV cameras recording motion in most common areas. They protect shared property and support observance of the Condo Docs and Handbook. Activity in key areas may be reviewed, but cameras are not a substitute for calling 911 in an emergency. Registered residents may formally request appropriate access to live images from entrance points, indoor parking, elevator/corridors, stairwells, hallways, outdoor parking, and recreation areas through Heritage and/or the Board." },
  { category: "Security: When to Call Community Watch", keywords: ["community watch", "doc", "derek cox", "tailgating", "loitering", "package theft", "mailroom", "suspicious"], answer: "Call 911 for active danger, crime, fire, or medical emergencies. For non-emergency concerns such as loitering, tailgating, unknown people in common areas, smoking/vaping in common areas, package/mailroom concerns, or people sitting in stairwells, contact Hillside Community Watch at 404-883-3350 or dial 811 from a Hillside callbox. Doc may check cameras or respond if appropriate." },
  { category: "Parking Rules: Detailed Restrictions", keywords: ["parking rules", "assigned space", "guest parking", "handicapped", "front parking", "towing"], answer: "Garage spaces are assigned to units. Residents and guests may not park in another resident’s assigned space without written permission. Vehicles may not remain in front of the building more than 30 minutes, may not park in the marked handicapped zone, and may not block fire/emergency access. Towed vehicles can be recovered through A-Tow at 404-577-8950 at the owner’s expense." },
  { category: "Unit Maintenance: Plumbing and AC Duties", keywords: ["plumbing", "ac drain", "air conditioner", "bleach", "filter", "water leak", "drain line"], answer: "Owners must maintain appliances, plumbing, and A/C systems to prevent damage to their own and neighboring units. A/C drains should be cleansed monthly with one cup of household bleach, and air-handler filters should be changed at least every three months. Shared drain lines must remain open during summer to prevent flooding from clogged pipelines." },
  { category: "Unit Maintenance: Fire Safety and Inspections", keywords: ["fire inspection", "sprinkler inspection", "smoke detector", "sprinkler head", "painted sprinkler", "annual inspection"], answer: "Owners must keep smoke detectors functional and must not paint sprinkler heads or sprinkler components. Annual fire alarm and sprinkler inspections are mandatory for everyone’s safety. If an owner cannot be present, written permission must be provided so inspectors may enter using the emergency access key in Board custody, with a Board member present." },
  { category: "Architectural Control: Submission Required", keywords: ["architectural submission", "acc", "renovation application", "board approval", "contractor insurance", "structural engineer"], answer: "Architectural submissions are reviewed by the Board and Architectural Control Committee before monthly Board meetings. Applications must include needed photos, drawings, cut sheets, permits, contractor insurance, and other information. Property owners must sign; tenant or contractor signatures for the owner are not accepted. Wall removal requires a structural engineer letter confirming no impact on structural integrity." },
  { category: "Architectural Control: No Work Before Approval", keywords: ["work before approval", "unapproved construction", "legal fees", "restore original condition", "permits"], answer: "No construction, alteration, or modification may begin without prior Board approval. Work started or completed without approval may have to be returned to original condition at the owner’s expense. Owners may be responsible for legal fees incurred by the HOA enforcing construction/application rules and remain responsible for permits, code compliance, and damages caused by their contractors." },
  { category: "Architectural Control: Construction Conduct", keywords: ["construction debris", "contractor debris", "neighbors", "construction noise", "sprinkler heads", "renovation noise"], answer: "Construction work must be neat and orderly, occur only during allowed hours, and comply with federal, state, county, city, and local codes. Construction debris must be removed safely and may not be disposed through trash chutes or the dumpster room. Neighbors should be notified in advance of expected noisy work. Sprinkler heads may never be painted." },
  { category: "Club Room Reservation Rules", keywords: ["club room reservation", "clubroom form", "reservation form", "mailbox 14", "deposit", "rental fee"], answer: "To reserve the club room, first email board@hillsideatlenox.com to confirm date availability. Submit the completed reservation form with a $150 rental fee and separate $200 refundable deposit check. Forms/checks may be placed in Homeowners’ Mail Slot box #14 or slipped under the office door in the club room. Events are limited to 25 guests and must end by 10 PM." },
  { category: "Club Room Conduct Rules", keywords: ["club room conduct", "pool table", "smoking", "vaping", "glitter", "confetti", "club room cleanup"], answer: "Club room guests must be accompanied by an authorized resident. Furniture may not be moved, including the pool table, and the pool is not included with the club room reservation. No smoking, vaping, glitter, or confetti. The reserving resident must clean up and is responsible for any damage." },
  { category: "Do and Do Not List", keywords: ["do not", "dos and don'ts", "rules list", "common rules", "prohibited"], answer: "Residents should keep dues current, clean up common areas, pick up pet waste, use designated pet areas, follow parking and amenity rules, and contact the Board with questions. Residents should not store personal items in parking spaces, allow pets in the lobby or through front doors except as allowed, smoke or vape in common areas/amenities, share access codes with non-residents, or use common areas in ways that disturb others." },
  { category: "Enforcement: Reporting Violations", keywords: ["report violation", "covenant violation", "condominium violation", "pictures", "witnesses", "hearsay"], answer: "Violations of the Condo Docs and Hillside rules should be reported to the Heritage Property Manager and the Board. If fines may be involved, provide witnesses, photos, and documentation when possible; hearsay alone is insufficient. Access-device records and camera footage may supplement violation documentation." },
  { category: "Enforcement: Fees Charged to Owner Account", keywords: ["owner account", "heritage account", "fines charged", "fees charged", "legal counsel"], answer: "Fees and fines are charged to the property owner’s account at Heritage Property Management. The pasted fine forms state that compliance with the condominium rules, Declaration, and Bylaws is mandatory and that the Board and owner may consult legal counsel to ensure enforceability." },
  { category: "Emergency and Property Damage Response", keywords: ["water backup", "sewage backup", "flood", "property damage", "gas leak", "fire death", "emergency"], answer: "For fire, death, illness, active danger, or critical gas/water leaks, call 911 first. For water/sewage backup, floods, and maintenance problems, contact the Heritage Property Manager. If the problem is common-area related, management coordinates repairs; if it is not common-area related, owners are responsible for service costs." },
  { category: "Management Company Authority", keywords: ["management company role", "heritage role", "property manager role", "financial affairs", "compliance", "covenant notices"], answer: "Heritage handles daily operations at the direction of the Board. Management handles financial affairs, payables, dues collection, monthly financial statements, annual budgets, records, bids for capital repairs, homeowner notices, and compliance administration. Heritage may issue covenant violation notices and assess fines as directed or deemed appropriate under Board authority." },
  { category: "Board Meeting and Contact Protocol", keywords: ["board contact", "board meeting", "third thursday", "quarterly meeting", "annual meeting", "contact board members"], answer: "The Board governs for the Association as a whole and should generally be contacted in writing at board@hillsideatlenox.com or through an Association meeting. It is inappropriate to call Board members at home or work or knock on their doors unless requested, authorized, or in a serious emergency. Board meetings are generally monthly, with quarterly and annual homeowner meetings." },
];

// Institutional source-of-truth knowledge from Hillside at Lenox Declaration/CCR and Bylaws.
// Lenox searches these entries first so resident and prospective-buyer answers are grounded in the legal documents.
const legalKnowledgeEntries = [
  { category: "CCR: Legal Framework and Governing Documents", keywords: ["ccr", "cc&r", "declaration", "bylaws", "articles", "condominium act", "governing documents", "condo docs", "legal framework"], answer: "Hillside at Lenox is governed by the Declaration of Condominium, Bylaws, Articles of Incorporation, recorded plats/plans, and the Georgia Condominium Act. The Declaration submits the property to the Georgia Condominium Act, O.C.G.A. §44-3-70 et seq. These documents run with the land and bind owners, occupants, tenants, guests, and successors." },
  { category: "CCR: Conflict Hierarchy", keywords: ["conflict", "which document controls", "precedence", "higher authority", "bylaws conflict", "handbook conflict"], answer: "If there is a conflict, the legal documents control over practical handbook guidance. Under the Bylaws conflict provision, the Act, Georgia Nonprofit Corporation Code where applicable, Declaration, Articles of Incorporation, and Bylaws control in that order where conflicts or inconsistencies exist. The Handbook should be treated as practical guidance that does not override the recorded legal documents." },
  { category: "CCR: Unit Boundaries", keywords: ["unit boundary", "walls", "windows", "doors", "hvac", "plumbing", "fixtures", "what do i own"], answer: "The Declaration defines each Unit by vertical and horizontal boundaries. Entry doors and exterior glass surfaces serving the Unit, windows/glass doors, HVAC systems serving only that Unit, ductwork, appliances, and plumbing fixtures within a Unit are treated as part of the Unit. Components serving more than one Unit or the Common Elements are generally Common Elements." },
  { category: "CCR: Common Elements", keywords: ["common elements", "hallways", "lobby", "pool", "garage", "mail area", "stairs", "elevator", "trash room", "common area"], answer: "Common Elements are all parts of the condominium not within Unit boundaries. They include shared areas such as entries, hallways, stairs, lobby/atrium, underground parking facility, lighting, mail area, elevators/mechanical areas, dumpster/trash rooms/chutes, and Association property/equipment/furniture in common areas. Owners share ownership as tenants-in-common according to their allocated percentage interests." },
  { category: "CCR: Limited Common Elements", keywords: ["limited common element", "parking space", "storage space", "balcony", "patio", "mailbox", "meter", "assigned parking"], answer: "Limited Common Elements are portions of Common Elements reserved for fewer than all Units. The Declaration lists examples including HVAC areas serving a Unit, utility meters serving one Unit, assigned parking spaces, storage spaces, patios/balconies serving one Unit, chimneys attached to a Unit, and each Unit’s mailbox/mail slot. The Board may assign or reassign Limited Common Elements as allowed by the Declaration and Georgia law." },
  { category: "CCR: Association Membership and Voting", keywords: ["membership", "member", "vote", "one vote", "voting rights", "eligible vote", "co-owner vote"], answer: "Ownership of a Unit automatically makes the owner a member of the Association. Each Unit has one equally weighted vote. If multiple people own one Unit, they still have only one vote for that Unit. A spouse or cohabitant may exercise member powers as provided in the Bylaws. Voting rights can be suspended under the Declaration/Bylaws, and suspended votes do not count toward majority or quorum." },
  { category: "Bylaws: Delinquent Voting Rights", keywords: ["delinquent", "late dues", "30 days", "can't vote", "voting suspended", "eligible vote"], answer: "Under the Bylaws, no Owner may vote in person or by proxy if the Owner is more than 30 days delinquent in any payment due the Association or if voting rights have been suspended for an infraction. Suspended voting rights are not counted as eligible votes for majority or quorum." },
  { category: "Bylaws: Majority Definition", keywords: ["majority", "majority vote", "what is majority", "50 percent"], answer: "Unless the Declaration or Bylaws require a different threshold, “majority” means more than 50% of the total number of eligible votes, owners, or other group as the context requires. A majority vote means more than 50% of those voting in person or by proxy, unless a higher threshold applies." },
  { category: "Bylaws: Member Meetings", keywords: ["annual meeting", "special meeting", "meeting notice", "21 days", "7 days", "15 percent", "member meeting"], answer: "Annual member meetings are held during the fourth quarter, with date/time/place set by the Board and not on a legal holiday. Special member meetings may be called by the President or Secretary, by request of two Board members, or by written petition of Owners holding at least 15% of total eligible Association vote. Annual meeting notice must be sent at least 21 days before the meeting; special meeting notice at least 7 days before." },
  { category: "Bylaws: Quorum and Proxies", keywords: ["quorum", "proxy", "written proxy", "one third", "adjournment", "ballot"], answer: "A quorum for owner meetings is the presence in person or by proxy of Owners entitled to cast one-third of eligible Association votes. Proxies must be written, signed, dated, and filed with the Secretary before the meeting. A proxy may be delivered personally, by U.S. mail, or by facsimile to a Board member or property manager. Presence by the proxy giver at the meeting invalidates that proxy for that meeting, and a later-dated proxy invalidates an earlier one." },
  { category: "Bylaws: Written Ballots and Consent", keywords: ["written ballot", "written consent", "action without meeting", "ballots", "consent"], answer: "At the Board’s discretion, member action may be taken without a meeting by written ballot or written consent. Ballots must state the proposed action and allow a vote for or against it, and approval is valid only if the number of votes cast meets quorum and approval thresholds. Written consents must meet the required voting power. Ballots are kept in Association files for at least three years." },
  { category: "Bylaws: Board Eligibility and Terms", keywords: ["board eligibility", "board term", "director eligibility", "serve on board", "board member", "two year term"], answer: "Except for declarant-appointed directors, Board directors must be Owners or spouses/cohabitants of Owners. An Owner and that Owner’s spouse/cohabitant may not serve at the same time, and co-owners may not serve at the same time. A person more than 60 days delinquent in an assessment or charge is not eligible to serve. Directors generally serve two-year terms after the initial transition structure." },
  { category: "Bylaws: Board Removal and Vacancies", keywords: ["remove board member", "board vacancy", "director removal", "60 days past due", "unexcused absences"], answer: "Board members, except declarant appointees, may be removed with or without cause by a majority of Association members entitled to elect that director. A director more than 60 days past due in assessments/charges is automatically removed even if later paid. Three consecutive unexcused absences from regular Board meetings may allow removal by majority vote of the other directors. Vacancies are generally filled by majority vote of remaining directors for the rest of the replaced director’s term." },
  { category: "Bylaws: Board Elections and Nominations", keywords: ["board election", "nominating committee", "nomination", "candidate", "cumulative voting", "written ballot"], answer: "Board elections have no cumulative voting. Candidates receiving the most votes fill the open seats, and Board elections are by written ballot unless unanimously waived at the meeting. A Nominating Committee should be appointed at least 30 days before the annual meeting, nominations should be made at least 14 days before, floor nominations are allowed, and candidates must have a reasonable opportunity to communicate qualifications." },
  { category: "Bylaws: Board Meetings", keywords: ["board meeting", "regular board meeting", "special board meeting", "open meeting", "executive session", "board quorum"], answer: "Regular Board meetings must be held at least once every six months, and the newly elected Board must meet within 10 days after each annual meeting. Special Board meetings may be called by the President or on written request of at least two directors with two days’ notice. Board meetings are open to members, though non-directors may not participate unless authorized. The Board may use executive session for personnel matters, litigation, and similar business after announcing the nature of the business in open session. A majority of directors is a Board quorum." },
  { category: "Bylaws: Board Powers", keywords: ["board powers", "budget", "assessments", "collect assessments", "rules", "fines", "insurance", "contracts", "books"], answer: "The Board manages Association affairs and has broad powers to prepare/adopt budgets, levy and collect assessments, maintain the Area of Common Responsibility, hire/dismiss personnel, collect/deposit/invest funds, make and amend rules, impose sanctions including monetary fines, open bank accounts, make repairs/improvements, enforce governing documents by legal means, carry insurance, pay common service costs, keep detailed books, and contract for duties/functions." },
  { category: "Bylaws: Management Agent and Borrowing", keywords: ["management agent", "property manager contract", "management contract", "borrowing", "loan", "borrow money"], answer: "The Association may hire a professional management agent at compensation set by the Board. Management contracts should be terminable by the Association with or without cause and without penalty on no more than 30 days’ written notice, and no management contract may exceed one year. The Board may borrow money for maintenance, repair, restoration, improvement of Common Elements/facilities, or other purposes only with approval of a majority of Association members." },
  { category: "Bylaws: Officers", keywords: ["president", "vice president", "secretary", "treasurer", "officer", "officers"], answer: "Principal officers are President, Secretary, and Treasurer; one person may hold multiple offices, and a Vice President may be elected at the Board’s discretion. Officers are elected annually by the Board at the first Board meeting after each annual meeting and serve at the pleasure of the Board. The President presides and acts as chief executive officer, the Secretary keeps minutes and books/papers as directed, and the Treasurer handles funds, financial records, statements, tax returns, deposits, and budget preparation duties." },
  { category: "Bylaws: Committees and ACC", keywords: ["committee", "architectural control committee", "acc", "service on committee", "other committees"], answer: "The Board must establish an Architectural Control Committee to establish and maintain architectural standards as provided in the Declaration. The Board may authorize other committees and define their powers/duties. Unless otherwise provided, committee members are appointed by the President, serve at the pleasure of the Board, and may be removed with or without cause." },
  { category: "Bylaws: Rulemaking Authority", keywords: ["rulemaking", "make rules", "modify rules", "repeal rules", "enforce rules", "rules and regulations"], answer: "The Board may make, modify, repeal, and enforce reasonable rules and regulations governing the conduct, use, and enjoyment of Units and Common Elements. Copies of rules must be furnished to Owners and Occupants. A rule may be repealed by affirmative vote or written consent of a majority of total Association vote and Declarant consent while Declarant retains applicable appointment rights." },
  { category: "Bylaws: Fines and Suspensions", keywords: ["fine", "fines", "suspension", "suspend rights", "common elements", "lien", "owner fine", "tenant fine"], answer: "The Board may impose reasonable fines that constitute a lien on the Owner’s Unit and may suspend an Owner’s right to vote or use Common Elements for violations of the Declaration, Bylaws, or duly adopted rules. The Association may not limit ingress or egress to or from a Unit. If an Occupant violates and does not pay the fine in the time set by the Board, the Unit Owner must pay it and it becomes an assessment/lien until paid." },
  { category: "Bylaws: Violation Notice and Hearing", keywords: ["violation notice", "hearing", "fine hearing", "contest fine", "reconsideration", "10 days"], answer: "Before imposing fines/suspensions, the Board must send written notice identifying the violation and fine(s), advising the violator of the right to request a Board hearing or reconsideration. Fines may begin when notice is sent or later as stated in the notice. For continuing violations, each day can be a separate offense and per-diem fines may be imposed without further notice. If a written hearing request is received within 10 days of the notice date, the Board holds an executive-session hearing and the minutes must include a written statement of results." },
  { category: "Bylaws: Additional Enforcement and Self-Help", keywords: ["self help", "towing", "enforcement rights", "maintenance after owner failure", "attorney fees", "abatement"], answer: "The Board may enforce the Declaration, Bylaws, and rules by self-help, including towing vehicles violating parking rules or performing maintenance on a Unit after the owner fails to do so, or by lawsuit to enjoin violations or recover damages. Responsible owners/occupants may be required to pay costs, including reasonable attorney fees. The Association or authorized agent may enter a Unit or Common Element portion to abate or remove violations after at least two days’ written notice before altering or demolishing construction items." },
  { category: "Bylaws: Financial Review and Audit", keywords: ["financial review", "audit", "financial statement", "120 days", "accountant", "fiscal year"], answer: "A financial review of Association accounts must be performed annually and a financial statement prepared. After receiving the reviewed statement at the annual meeting, Owners may by majority vote require an independent audit as a Common Expense. Financial statements must be available to first mortgage holders/insurers/guarantors on written request within 120 days of fiscal year end. If the condominium contains 50 or more Units, accounts are audited annually as a Common Expense." },
  { category: "Bylaws: Amendment Requirements", keywords: ["amend bylaws", "amendment", "two thirds", "2/3", "recorded", "challenge amendment"], answer: "Except where a higher vote is required, Bylaws may be amended by affirmative vote, written consent, or combination of both from members holding two-thirds of total Association vote, plus Declarant consent while Declarant owns a Unit in the Condominium and retains applicable rights. No amendment is effective until certified by the President and Secretary and recorded in Fulton County land records. Challenges to validity must be brought within one year of the amendment’s effective date." },
  { category: "Bylaws: Books and Records", keywords: ["books and records", "inspect records", "records request", "minutes", "financial records", "membership list", "5 days"], answer: "Members and first mortgage holders may inspect specified Association records at a reasonable time/location on written request at least five business days before inspection. Records include Articles, Bylaws, certain resolutions, member-meeting minutes/actions for the past three years, communications/financial statements from the past three years, current directors/officers list, and most recent annual report. Some records require good faith, proper purpose, and reasonable particularity. Confidential/privileged items may be limited or withheld, including attorney-client communications, executive-session minutes, and other members’ financial/account records. Minutes become official only after approval." },
  { category: "CCR: Association Entry Rights", keywords: ["enter unit", "emergency entry", "maintenance entry", "security entry", "reasonable notice", "unit access"], answer: "The Declaration gives the Association, acting through the Board and authorized agents, the right to enter Units for maintenance, emergency, security, or safety purposes. Police, fire, ambulance, and similar emergency personnel may also enter in performing duties. Except in emergencies, entry should occur during reasonable hours and after reasonable notice to the Owner or Occupant." },
  { category: "CCR: Assessment Purpose and Obligation", keywords: ["assessment", "assessments", "common expenses", "special assessment", "annual assessment", "personal obligation", "lien"], answer: "The Association may levy assessments for Common Expenses to promote the recreation, health, safety, welfare, common benefit, and enjoyment of Owners and Occupants. By accepting a deed, each Owner agrees to pay annual assessments, special assessments, specific assessments, and any other charges authorized by the Declaration/Act. Assessments are both a personal obligation and can become a lien against the Unit." },
  { category: "CCR: Special Assessments and Individual Charges", keywords: ["special assessment", "specific assessment", "individual charge", "damage charge", "utility charge"], answer: "The Board may levy special assessments as allowed by the Declaration and Georgia Condominium Act. Common Expenses benefiting fewer than all Units or disproportionately benefiting some Units may be specially assessed equitably. Costs caused by the conduct of an Owner, Occupant, licensee, or invitee may be specially assessed to the responsible Unit. The Board may assess individual utility usage charges, submeter, or install separate meters." },
  { category: "CCR: Insurance Coverage", keywords: ["insurance", "association insurance", "unit insurance", "fixtures", "betterments", "casualty", "liability"], answer: "The Association must maintain insurance as a Common Expense as required by the Georgia Condominium Act and the Declaration. The policy may cover certain property within Units such as fixtures, improvements, alterations, and appliances, or may exclude owner betterments and finished surfaces depending on the policy structure. Owners should maintain their own coverage for personal property, owner responsibilities, deductibles, and gaps not covered by Association insurance." },
  { category: "CCR: Repair and Reconstruction", keywords: ["repair", "reconstruction", "casualty", "fire damage", "damage", "80 percent", "rebuild"], answer: "After fire or other casualty damage, the Board or authorized agent arranges prompt repair and restoration unless 80% of Unit Owners, including owners of damaged Units, vote not to proceed. First mortgage holders are entitled to notice of substantial damage or destruction. Insurance proceeds and owner/Association obligations are handled under the Declaration and Act." },
  { category: "CCR: Architectural Controls", keywords: ["architectural control", "architecture", "exterior change", "paint", "landscaping", "sign", "window treatments", "alteration", "construction"], answer: "The Declaration requires architectural controls for encroachments onto Common or Limited Common Elements, exterior changes/alterations/construction, painting, landscaping, and placement/posting of exterior objects, signs, clotheslines, speakers, playground equipment, lights, fountains, flags, or similar items. Owners should obtain required approval before making covered changes. Window treatments visible from outside and exterior/common-area changes are especially sensitive." },
  { category: "CCR: Use Restrictions - Owner Responsibility", keywords: ["use restrictions", "owner responsible", "tenant violation", "guest violation", "family guest tenant occupant", "rules"], answer: "Each Unit Owner is responsible for ensuring the owner’s family, guests, tenants, and occupants comply with the Condominium Instruments and Association rules. The Association may take action against the Owner for violations by family, guests, tenants, or occupants as if the Owner committed the violation together with them." },
  { category: "CCR: Residential Use and Business Activity", keywords: ["residential use", "business", "commercial", "home business", "professional use"], answer: "The Declaration’s Use Restrictions govern how Units may be used. Lenox should answer residential-use/business-use questions conservatively: Units are intended for condominium residential use, and any business or professional activity must not violate the Declaration, rules, laws, occupancy restrictions, nuisance standards, signage/exterior restrictions, or insurance/traffic/common-area impacts. When in doubt, residents should request Board/management review before proceeding." },
  { category: "CCR: Nuisance and Offensive Activity", keywords: ["nuisance", "noise", "offensive activity", "annoyance", "hazard", "disturbance"], answer: "The Declaration’s use restrictions are intended to prevent conduct that interferes with other residents’ use and enjoyment, creates nuisance or hazard, or violates the community standard. Lenox should route ongoing nuisance/noise/safety issues to Heritage and the Board with documentation and advise emergencies or active danger go to 911 first." },
  { category: "CCR: Leasing Core Rule", keywords: ["leasing", "lease", "rent", "rental", "leasing permit", "hardship permit", "lease my unit"], answer: "The Declaration says leasing is restricted to preserve the condominium as predominantly owner-occupied and to maintain financing eligibility. Except as allowed by the leasing section, leasing is prohibited. Owners may lease only if they apply for and receive a leasing permit or hardship leasing permit from the Board and comply strictly with the permit and Declaration conditions." },
  { category: "CCR: Leasing Permit Conditions", keywords: ["leasing permit conditions", "hardship leasing permit", "lease conditions", "board leasing authority"], answer: "The Board has authority to establish conditions for leasing permits and hardship leasing permits consistent with the Declaration. A leasing permit allows leasing only under the permit terms and the leasing section. Owners and tenants remain bound by the Declaration, Bylaws, and rules, and violations can affect the owner’s rights and permit status." },
  { category: "CCR: Sale of Units Notice", keywords: ["sale of unit", "sell unit", "transfer notice", "buyer notice", "purchaser", "closing"], answer: "An owner intending to transfer or sell a Unit must give written notice to the Board within seven days after execution of transfer/sales documents, including the intended grantee’s name/address and other reasonably required information. This does not create a right of first refusal. Within seven days after receiving title, the purchaser must give written ownership notice to the Board." },
  { category: "CCR: Owner Maintenance Responsibility", keywords: ["maintenance responsibility", "owner maintenance", "windows", "doors", "hvac", "appliances", "limited common elements"], answer: "Each Owner must maintain and keep in good repair the Unit and owner-made improvements to Limited Common Elements assigned to the Unit, except portions expressly assigned to the Association. Owner responsibility includes items such as glass surfaces, windows/window frames/casings/locks, doors/door frames/hardware that are part of the Unit entry system, Unit HVAC/appliances/plumbing fixtures, and other Unit components as detailed in the Declaration." },
  { category: "CCR: Association Maintenance Responsibility", keywords: ["association maintenance", "common area repair", "common elements maintenance", "area of common responsibility"], answer: "The Association maintains, repairs, and replaces Common Elements and other Areas of Common Responsibility assigned to it by the Declaration. The Board controls common-area maintenance and may specially assess costs where permitted, including when costs are caused by a particular Unit, Owner, Occupant, guest, licensee, or invitee." },
  { category: "CCR: Mortgagee Rights", keywords: ["mortgagee", "lender", "first mortgage", "mortgage holder", "lender approval"], answer: "The Declaration grants first mortgagees certain notice and approval rights. Without required consent thresholds, the Association/membership generally may not terminate the condominium, alter pro rata interests/obligations, partition/subdivide inconsistently, abandon or transfer Common Elements except as allowed, or make certain insurance/priority changes. Lenox should route mortgagee/legal approval questions to the Board/management and legal counsel." },
  { category: "CCR: Security Disclaimer", keywords: ["security", "crime", "safety", "gate", "cameras", "association guarantee", "criminal acts"], answer: "The Declaration states the Association or Declarant may provide measures that directly or indirectly improve safety, but neither is a provider of security and neither guarantees that non-owners/non-occupants will not gain access or commit criminal acts. Residents remain responsible for personal safety precautions and should call 911 for emergencies." },
  { category: "CCR: Easements and Access", keywords: ["easement", "access", "ingress", "egress", "common elements access", "use common elements"], answer: "Each Unit Owner and Occupant has a non-exclusive easement to use and enjoy the Common Elements, including access/ingress/egress to and from the Unit over designated areas, subject to Limited Common Element rights and the Association’s right to control use and enjoyment under the Declaration, including suspension of voting/use privileges where allowed." },
  { category: "CCR: Amend Declaration", keywords: ["amend declaration", "declaration amendment", "two thirds", "2/3 vote", "record amendment"], answer: "Except where a higher vote is required, the Declaration may be amended by affirmative vote, written consent, or combination of both from members holding two-thirds of total Association vote. Declarant consent is required while Declarant retains the right to appoint directors/officers. Notices for meetings considering amendments must identify the fact and subject of the proposed amendment, and effective amendments must be properly certified/recorded." },
  { category: "Lenox Legal Answering Rule", keywords: ["legal answer", "legal advice", "source of truth", "institutional knowledge", "prospective homeowner", "resident question"], answer: "Lenox should answer resident and prospective-homeowner questions from the Declaration/CCR, Bylaws, Handbook, and Board-approved Supabase knowledge. Lenox should explain the relevant rule in plain English, identify when Board/management review is needed, and avoid presenting itself as a lawyer. For legal interpretation, enforcement disputes, amendments, liens, insurance, lender rights, or owner-specific liability, Lenox should recommend contacting the Board/management and qualified counsel." },
];

function Card({ children, className = "" }) { return <div className={`card ${className}`}>{children}</div>; }
function Badge({ children, className = "" }) { return <span className={`badge ${className}`}>{children}</span>; }

const stopWords = new Set(["a", "an", "and", "are", "as", "at", "be", "by", "can", "do", "does", "for", "from", "has", "have", "how", "i", "if", "in", "is", "it", "me", "my", "of", "on", "or", "our", "the", "their", "to", "we", "what", "when", "where", "who", "why", "with", "you", "your"]);

function wordsFrom(value) {
  return String(value || "").toLowerCase().replace(/[^a-z0-9$]+/g, " ").split(/\s+/).filter((word) => word.length > 2 && !stopWords.has(word));
}

function scoreKnowledgeItem(item, normalizedQuestion, questionWords) {
  let score = 0;
  const keywords = (item.keywords || []).map((keyword) => String(keyword).toLowerCase());
  keywords.forEach((keyword) => {
    if (normalizedQuestion.includes(keyword)) score += keyword.includes(" ") ? 12 : 8;
  });
  const searchableWords = new Set(wordsFrom(`${item.category} ${(item.keywords || []).join(" ")} ${item.answer}`));
  questionWords.forEach((word) => {
    if (searchableWords.has(word)) score += 2;
  });
  return score;
}

function findKnowledgeMatch(message, sources) {
  const normalized = message.toLowerCase();
  const questionWords = wordsFrom(message);
  const ranked = sources
    .map((item) => ({ item, score: scoreKnowledgeItem(item, normalized, questionWords) }))
    .sort((a, b) => b.score - a.score);
  return ranked[0]?.score >= 4 ? ranked[0].item : null;
}

function staticResponse(message) {
  const normalized = message.toLowerCase();
  const violation = violationRules.find((item) => item.keywords.some((keyword) => normalized.includes(keyword)));
  if (violation && ["can i", "what happens", "allowed", "violation", "fine", "tow", "report"].some((word) => normalized.includes(word))) {
    return { title: `Violation Intelligence: ${violation.title}`, text: `Risk Level: ${violation.severity}\n\nRule: ${violation.rule}\n\nPotential Consequence: ${violation.consequence}\n\nRecommended Action: ${violation.action}\n\nFormal enforcement should be handled by the Property Manager and/or Board with supporting documentation.` };
  }
  const match = findKnowledgeMatch(message, [...legalKnowledgeEntries, ...knowledgeBase, ...handbookEntries]);
  if (match) return { title: match.category, text: match.answer };
  return { title: "Need a human follow-up", text: `I do not have a confident approved answer yet. I’ve added this question to the learning queue for Board review. For urgent matters, contact Amber Nash or the Board at ${BOARD_EMAIL}. For emergencies, call 911 first.` };
}

export default function Home() {
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState([{ role: "assistant", title: "Welcome", text: "Good day. I’m Lenox — the Hillside at Lenox resident assistant. Ask about parking, amenities, maintenance, violations, new-resident steps, or who to contact." }]);
  const [speechEnabled, setSpeechEnabled] = useState(true);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [britishVoice, setBritishVoice] = useState(null);
  const premiumAudioRef = useRef(null);
  const [adminOpen, setAdminOpen] = useState(false);
  const [adminUnlocked, setAdminUnlocked] = useState(false);
  const [adminPassword, setAdminPassword] = useState("");
  const [adminError, setAdminError] = useState("");
  const [learningQueue, setLearningQueue] = useState([]);
  const [approvedKnowledge, setApprovedKnowledge] = useState([]);
  const [selectedLearningId, setSelectedLearningId] = useState(null);
  const [newDocument, setNewDocument] = useState({ title: "", category: "", keywords: "", content: "" });
  const [notice, setNotice] = useState("");
  const [importingHandbook, setImportingHandbook] = useState(false);
  const selectedLearning = learningQueue.find((item) => item.id === selectedLearningId) || learningQueue[0];
  const stats = useMemo(() => [{ label: "Topics Covered", value: "90+" }, { label: "Resident Support", value: "24/7" }, { label: "Legal Docs Brain", value: "Active" }], []);

  async function loadKnowledge() {
    if (!supabase) return;
    const { data, error } = await supabase.from("lenox_approved_knowledge").select("*").order("approved_at", { ascending: false });
    if (!error) setApprovedKnowledge((data || []).map((item) => ({ category: item.category, keywords: Array.isArray(item.keywords) ? item.keywords : [], answer: item.answer })));
  }

  async function loadQueue() {
    if (!supabase) return;
    const { data, error } = await supabase.from("lenox_learning_queue").select("*").order("created_at", { ascending: false });
    if (!error) {
      const rows = (data || []).map((item) => ({ id: item.id, question: item.question, suggestedCategory: item.suggested_category || "New Resident Question", suggestedKeywords: item.suggested_keywords || "", suggestedAnswer: item.suggested_answer || "", status: item.status || "pending" }));
      setLearningQueue(rows);
      setSelectedLearningId(rows[0]?.id || null);
    }
  }

  useEffect(() => { loadKnowledge(); }, []);
  useEffect(() => { if (adminUnlocked) loadQueue(); }, [adminUnlocked]);
  useEffect(() => {
    if (typeof window === "undefined" || !window.speechSynthesis) return undefined;
    const chooseVoice = () => {
      const voices = window.speechSynthesis.getVoices();
      const preferred = voices.find((voice) => voice.lang === "en-GB" && /Daniel|George|Arthur|Oliver|UK|British/i.test(voice.name))
        || voices.find((voice) => voice.lang === "en-GB")
        || voices.find((voice) => /^en/i.test(voice.lang))
        || voices[0]
        || null;
      setBritishVoice(preferred);
    };
    chooseVoice();
    window.speechSynthesis.onvoiceschanged = chooseVoice;
    return () => {
      premiumAudioRef.current?.pause();
      window.speechSynthesis.cancel();
      window.speechSynthesis.onvoiceschanged = null;
    };
  }, []);

  function speakWithBrowserVoice(title, text) {
    if (!speechEnabled || typeof window === "undefined" || !window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const cleanText = String(text || "").replace(/\s+/g, " ").slice(0, 900);
    const utterance = new SpeechSynthesisUtterance(`Good day. ${title}. ${cleanText}`);
    if (britishVoice) utterance.voice = britishVoice;
    utterance.lang = britishVoice?.lang || "en-GB";
    utterance.rate = 0.92;
    utterance.pitch = 1.05;
    utterance.onstart = () => setIsSpeaking(true);
    utterance.onend = () => setIsSpeaking(false);
    utterance.onerror = () => setIsSpeaking(false);
    window.speechSynthesis.speak(utterance);
  }

  async function speakAsLenox(title, text) {
    if (!speechEnabled || typeof window === "undefined") return;
    const cleanText = String(text || "").replace(/\s+/g, " ").slice(0, 1200);
    try {
      premiumAudioRef.current?.pause();
      window.speechSynthesis?.cancel();
      const response = await fetch("/api/lenox-voice", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text: `Good day. ${title}. ${cleanText}` }),
      });
      if (!response.ok) throw new Error("Premium voice unavailable");
      const audioBlob = await response.blob();
      const audioUrl = URL.createObjectURL(audioBlob);
      const audio = new Audio(audioUrl);
      premiumAudioRef.current = audio;
      audio.onplay = () => setIsSpeaking(true);
      audio.onended = () => { setIsSpeaking(false); URL.revokeObjectURL(audioUrl); };
      audio.onerror = () => { setIsSpeaking(false); URL.revokeObjectURL(audioUrl); speakWithBrowserVoice(title, text); };
      await audio.play();
    } catch {
      speakWithBrowserVoice(title, text);
    }
  }

  function toggleSpeech() {
    const next = !speechEnabled;
    setSpeechEnabled(next);
    if (!next && typeof window !== "undefined") {
      premiumAudioRef.current?.pause();
      window.speechSynthesis?.cancel();
      setIsSpeaking(false);
    }
  }

  async function sendQuestion(preset) {
    const outgoing = (preset || input).trim();
    if (!outgoing) return;
    const learned = findKnowledgeMatch(outgoing, [...legalKnowledgeEntries, ...approvedKnowledge, ...handbookEntries, ...knowledgeBase]);
    const response = learned ? { title: learned.category, text: learned.answer } : staticResponse(outgoing);
    setMessages((current) => [...current, { role: "user", text: outgoing }, { role: "assistant", ...response }]);
    speakAsLenox(response.title, response.text);
    setInput("");
    if (response.title !== "Need a human follow-up") return;

    const local = { id: `local-${Date.now()}`, question: outgoing, suggestedCategory: "New Resident Question", suggestedKeywords: outgoing.toLowerCase().split(/\s+/).slice(0, 6).join(", "), suggestedAnswer: "Draft an approved Hillside response here before publishing this answer to Lenox.", status: "pending" };
    if (adminUnlocked) { setLearningQueue((current) => [local, ...current]); setSelectedLearningId(local.id); }
    if (supabase) await supabase.from("lenox_learning_queue").insert({ question: local.question, suggested_category: local.suggestedCategory, suggested_keywords: local.suggestedKeywords, suggested_answer: local.suggestedAnswer, status: local.status });
  }

  async function unlockAdmin(event) {
    event.preventDefault(); setAdminError("");
    try {
      const response = await fetch("/api/board-session", { method: "POST", headers: { "Content-Type": "application/json" }, credentials: "same-origin", body: JSON.stringify({ password: adminPassword }) });
      if (!response.ok) throw new Error((await response.json().catch(() => ({}))).error || "Incorrect password");
      setAdminPassword(""); setAdminUnlocked(true);
    } catch (error) { setAdminError(error.message || "Could not verify Board access."); }
  }

  function updateSelected(field, value) { setLearningQueue((current) => current.map((item) => item.id === selectedLearning?.id ? { ...item, [field]: value } : item)); }
  async function approveSelected() {
    if (!selectedLearning || !selectedLearning.suggestedAnswer.trim()) return;
    const item = { category: selectedLearning.suggestedCategory.trim(), keywords: selectedLearning.suggestedKeywords.split(",").map((word) => word.trim()).filter(Boolean), answer: selectedLearning.suggestedAnswer.trim() };
    if (supabase) {
      const { error } = await supabase.from("lenox_approved_knowledge").insert(item);
      if (error) { setNotice(error.message); return; }
      if (!String(selectedLearning.id).startsWith("local-")) await supabase.from("lenox_learning_queue").delete().eq("id", selectedLearning.id);
    }
    setApprovedKnowledge((current) => [item, ...current]);
    setLearningQueue((current) => current.filter((row) => row.id !== selectedLearning.id));
    setNotice("Answer approved and added to Lenox.");
  }
  async function rejectSelected() { if (!selectedLearning) return; if (supabase && !String(selectedLearning.id).startsWith("local-")) await supabase.from("lenox_learning_queue").delete().eq("id", selectedLearning.id); setLearningQueue((current) => current.filter((row) => row.id !== selectedLearning.id)); }
  async function saveDocument(event) {
    event.preventDefault();
    if (!newDocument.title.trim() || !newDocument.category.trim() || !newDocument.keywords.trim() || !newDocument.content.trim()) { setNotice("Complete all four document fields."); return; }
    // Existing schema has category, keywords, and answer. Preserve the title in the approved answer itself.
    const item = { category: newDocument.category.trim(), keywords: newDocument.keywords.split(",").map((word) => word.trim()).filter(Boolean), answer: `Document: ${newDocument.title.trim()}\n\n${newDocument.content.trim()}` };
    if (supabase) { const { error } = await supabase.from("lenox_approved_knowledge").insert(item); if (error) { setNotice(error.message); return; } }
    setApprovedKnowledge((current) => [item, ...current]); setNewDocument({ title: "", category: "", keywords: "", content: "" }); setNotice("Document saved to approved knowledge.");
  }
  async function addResidentTutorial() {
    const item = { category: "New Resident Tutorial", keywords: ["new resident", "welcome", "move in", "first steps", "Hillside at Lenox"], answer: "Document: New Resident Tutorial\n\nWelcome to Hillside at Lenox. Review community rules and move-in procedures, register your contact information with management, learn amenity access procedures, and save the Board email: board@hillsideatlenox.com. Amber Nash, CMCA, can help with management questions at 770-200-8610 or anash@heritageproperty.com." };
    if (supabase) { const { error } = await supabase.from("lenox_approved_knowledge").insert(item); if (error) { setNotice(error.message); return; } }
    setApprovedKnowledge((current) => [item, ...current]); setNotice("New Resident Tutorial added to approved knowledge.");
  }
  async function importHandbook() {
    if (!supabase) { setNotice("Supabase is not connected, so the handbook cannot be saved yet."); return; }
    setImportingHandbook(true); setNotice("");
    const existing = new Set(approvedKnowledge.map((item) => item.category));
    const sourceEntries = [...legalKnowledgeEntries, ...handbookEntries];
    const entriesToAdd = sourceEntries.filter((item) => !existing.has(item.category));
    if (!entriesToAdd.length) { setNotice("The legal documents and May 2026 handbook have already been added."); setImportingHandbook(false); return; }
    const { error } = await supabase.from("lenox_approved_knowledge").insert(entriesToAdd);
    if (error) setNotice(`Handbook import failed: ${error.message}`);
    else { setApprovedKnowledge((current) => [...entriesToAdd, ...current]); setNotice(`Legal documents and handbook added: ${entriesToAdd.length} knowledge topics are now available to Lenox.`); }
    setImportingHandbook(false);
  }
  async function toggleAdmin() {
    const opening = !adminOpen;
    setAdminOpen(opening);
    if (!opening || adminUnlocked) return;
    const response = await fetch("/api/board-session", { credentials: "same-origin" }).catch(() => null);
    const body = response ? await response.json().catch(() => ({})) : {};
    if (response?.ok && body.authenticated) setAdminUnlocked(true);
  }
  function focusChat() { document.querySelector("#lenox-chat-input")?.scrollIntoView({ behavior: "smooth", block: "center" }); document.querySelector("#lenox-chat-input")?.focus(); }
  const lastAssistantMessage = [...messages].reverse().find((message) => message.role === "assistant");

  return <main className="page"><section className="layout"><div className="leftColumn">
    <Card><div className="heroHeader"><div className="brandIcon"><Building2 size={26} /></div><div><p className="eyebrow">Hillside at Lenox Digital Concierge</p><h1>Ask Lenox</h1></div></div><p className="lead">Lenox answers resident questions, reinforces handbook rules, routes residents to the right contacts, and learns from Board-approved answers.</p><div className="stats">{stats.map((item) => <div className="stat" key={item.label}><p className="statValue">{item.value}</p><p className="statLabel">{item.label}</p></div>)}</div></Card>
    <Card className="redCard"><div className="sectionTop"><div><p className="eyebrow redText">Violation Intelligence Mode</p><h2>Detect risk, explain the rule, and guide next steps</h2></div><Badge className="redBadge">Active</Badge></div><div className="featureGrid four">{violationRules.slice(0, 4).map((rule) => <div className="feature" key={rule.title}><AlertTriangle size={20} /><h3>{rule.title}</h3><p className="severity">{rule.severity} Risk</p><p>{rule.consequence}</p></div>)}</div></Card>
    <div className="featureGrid four">{[{ icon: Car, title: "Parking Enforcement", text: "Reinforces the 30-minute front parking rule and towing risk." }, { icon: Waves, title: "Amenity Rules", text: "Answers pool, sauna, club room, and fitness room questions." }, { icon: ShieldCheck, title: "Rules & Violations", text: "Explains community expectations and next steps." }, { icon: ConciergeBell, title: "Management Routing", text: "Directs residents to the correct Hillside contact channel." }].map(({ icon: Icon, title, text }) => <div className="feature mini" key={title}><Icon size={20} /><h3>{title}</h3><p>{text}</p></div>)}</div>
    <Card><div className="sectionTop"><div><p className="eyebrow">Board Access</p><h2>Admin Learning Dashboard</h2></div><button className="outlineButton" onClick={toggleAdmin}>{adminOpen ? "Close Admin" : "Open Admin"}</button></div>{adminOpen && (!adminUnlocked ? <form className="formStack" onSubmit={unlockAdmin}><label>Board password<input type="password" autoComplete="current-password" value={adminPassword} onChange={(event) => setAdminPassword(event.target.value)} placeholder="Enter board password" required /></label><button className="primaryButton">Unlock Admin</button>{adminError && <p className="errorText">{adminError}</p>}</form> : <div className="adminGrid"><div className="adminPanel"><div className="sectionTop compact"><h3>Pending questions</h3><Badge>{learningQueue.length} pending</Badge></div><div className="queueList">{learningQueue.length ? learningQueue.map((item) => <button key={item.id} className={`queueItem ${selectedLearning?.id === item.id ? "selected" : ""}`} onClick={() => setSelectedLearningId(item.id)}><strong>{item.question}</strong><span>{item.status}</span></button>) : <p className="muted">No pending resident questions right now.</p>}</div></div><div className="adminPanel">{selectedLearning ? <div className="formStack"><label>Resident question<div className="readonlyBox">{selectedLearning.question}</div></label><label>Approved answer category<input value={selectedLearning.suggestedCategory} onChange={(event) => updateSelected("suggestedCategory", event.target.value)} /></label><label>Keywords Lenox should recognize<input value={selectedLearning.suggestedKeywords} onChange={(event) => updateSelected("suggestedKeywords", event.target.value)} /></label><label>Approved answer<textarea value={selectedLearning.suggestedAnswer} onChange={(event) => updateSelected("suggestedAnswer", event.target.value)} /></label><div className="buttonRow"><button className="primaryButton" onClick={approveSelected}>Approve and add to Lenox</button><button className="outlineButton" onClick={rejectSelected}>Reject</button></div></div> : <p className="muted">Select a pending question to review.</p>}</div></div>)}{adminOpen && adminUnlocked && <form className="formStack teachForm" onSubmit={saveDocument}><div className="sectionTop compact"><h3>Teach Lenox From New Document</h3><button type="button" className="outlineButton" onClick={addResidentTutorial}>New Resident Tutorial</button></div><label>Document Title<input value={newDocument.title} onChange={(event) => setNewDocument({ ...newDocument, title: event.target.value })} required /></label><label>Category<input value={newDocument.category} onChange={(event) => setNewDocument({ ...newDocument, category: event.target.value })} required /></label><label>Keywords <span className="muted">(comma-separated)</span><input value={newDocument.keywords} onChange={(event) => setNewDocument({ ...newDocument, keywords: event.target.value })} required /></label><label>Document Content<textarea value={newDocument.content} onChange={(event) => setNewDocument({ ...newDocument, content: event.target.value })} required /></label><button className="primaryButton">Save to approved knowledge</button>{notice && <p className="muted">{notice}</p>}</form>}</Card>
    {adminOpen && adminUnlocked && <Card className="teachForm"><div className="sectionTop compact"><div><p className="eyebrow">One-time knowledge import</p><h3>Add Bylaws, CCR, and Handbook</h3></div><button type="button" className="primaryButton" disabled={importingHandbook} onClick={importHandbook}>{importingHandbook ? "Adding source docs…" : "Add source docs to Lenox"}</button></div><p className="muted">This saves the Bylaws, CCR, and handbook as searchable, Board-approved topics in Lenox’s knowledge base. It will not create duplicate topics.</p>{notice && <p className="muted">{notice}</p>}</Card>}
    <Card><h2>Key contacts Lenox can reference</h2><div className="contactGrid">{Object.values(contacts).map((value) => <div className="contact" key={value}>{value}</div>)}</div><div className="actionsBlock"><h3>Quick resident actions</h3><div className="actionGrid">{actionButtons.map(({ label, href, icon: Icon }) => <a key={label} href={href} target={href.startsWith("http") ? "_blank" : undefined} rel={href.startsWith("http") ? "noreferrer" : undefined} className="actionButton"><Icon size={16} />{label}</a>)}</div></div></Card>
  </div><aside className="chatCard"><div className="chatHeader"><div className="avatarWrap"><div className={`rabbitAvatar ${isSpeaking ? "talking" : ""}`} aria-label="Lenox rabbit avatar"><span className="rabbitEar leftEar" /><span className="rabbitEar rightEar" /><span className="rabbitFace"><span className="rabbitEye leftEye" /><span className="rabbitEye rightEye" /><span className="rabbitNose" /><span className="rabbitMouth" /></span></div><div><h2>Ask Lenox</h2><p>{isSpeaking ? "Lenox is speaking" : "Your Hillside Concierge"}</p></div></div><div className="voiceControls"><Badge>{britishVoice ? "Premium Voice" : "Voice Ready"}</Badge><button type="button" className={`voiceButton ${speechEnabled ? "active" : ""}`} onClick={toggleSpeech}>{speechEnabled ? "Voice On" : "Muted"}</button></div></div><div className="quickPrompts">{quickPrompts.map((prompt) => <button key={prompt} onClick={() => sendQuestion(prompt)}>{prompt}</button>)}</div><div className="messages">{messages.map((message, index) => <div key={index} className={`messageRow ${message.role === "user" ? "right" : "left"}`}><div className={`bubble ${message.role}`}>{message.title && message.role === "assistant" && <p className="bubbleTitle">{message.title}</p>}<p>{message.text}</p></div></div>)}</div><div className="composer"><input id="lenox-chat-input" value={input} onChange={(event) => setInput(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") sendQuestion(); }} placeholder="Ask Lenox about parking, amenities, or contacts..." /><button onClick={() => sendQuestion()} aria-label="Send message"><Send size={18} /></button></div><div className="chatActions"><a href="tel:7702008610">Call Amber</a><a href="mailto:anash@heritageproperty.com">Email Amber</a><a href={`mailto:${BOARD_EMAIL}`}>Email Board</a></div></aside></section>
    <motion.div className={`lenoxPresence ${isSpeaking ? "active" : "idle"}`} aria-live="polite" onClick={focusChat} initial={{ opacity: 0, y: 18, scale: 0.78 }} animate={{ opacity: isSpeaking ? 1 : 0.92, y: isSpeaking ? 0 : 10, scale: isSpeaking ? 1 : 0.76 }} transition={{ duration: 0.32 }}><div className="presenceSpeech"><strong>{isSpeaking ? (lastAssistantMessage?.title || "Ask Lenox") : "Good day, I’m Lenox"}</strong><span>Your Hillside Concierge</span></div><div className="largeRabbit" aria-label="Animated Lenox rabbit"><span className="largeEar largeLeftEar" /><span className="largeEar largeRightEar" /><span className="largeHead"><span className="largeEye largeLeftEye" /><span className="largeEye largeRightEye" /><span className="largeNose" /><span className="largeMouth" /><span className="largeCheek leftCheek" /><span className="largeCheek rightCheek" /></span><span className="largeBody"><span className="bowTie" /></span></div></motion.div>
    <motion.button className="lenoxFloat" onClick={focusChat} aria-label="Ask Lenox" initial={{ opacity: 0, scale: 0.8, y: 20 }} animate={{ opacity: 1, scale: 1, y: 0 }} whileHover={{ scale: 1.04 }}><span className="floatGlow" /><span className="helpBubble">Need help?</span><span className="floatInner"><span className={`miniRabbit ${isSpeaking ? "talking" : ""}`} /><span className="floatText"><strong>Ask Lenox</strong><small>Your Hillside Concierge</small></span></span></motion.button>
  </main>;
}
